// Pure (spec-like) definition over natural numbers.
pub fn triangle(n: u64) -> u64 {
    match n {
        0 => 0,
        _ => n + triangle(n - 1),
    }
}

// “Proof” function (non-formal in Rust): checks monotonicity for given i, j
// by computing both sides. This is a runtime check that can be used in tests.
pub fn triangle_is_monotonic(i: u64, j: u64) {
    assert!(i <= j, "precondition i <= j violated");
    let ti = triangle(i);
    let tj = triangle(j);
    assert!(ti <= tj, "triangle is not monotonic for the given inputs");
}

// Tail-recursive procedure updating `sum` from triangle(idx) to triangle(n).
// Preconditions (as described):
// - idx <= n
// - *sum == triangle(idx)
// - triangle(n) fits in u32 (no overflow in intermediate additions)
pub fn tail_triangle(n: u32, idx: u32, sum: &mut u32) {
    if idx == n {
        return;
    }
    // next index is idx + 1; safe because idx < n <= u32::MAX
    let next = idx + 1;

    // Addition is assumed not to overflow due to problem statement guarantees.
    *sum = sum.wrapping_add(next);

    // Tail recursion: measure (n - idx) strictly decreases by 1 each step.
    tail_triangle(n, next, sum);
}

